css:
.d1119-new,.d1119-new2,.d1119-roll,.d1119-arr{transform-box:fill-box}
.d1119-new{animation:d1119-up 3.6s ease-in-out infinite}
.d1119-new2{animation:d1119-up 3.6s ease-in-out infinite;animation-delay:.3s}
.d1119-arr{animation:d1119-nudge 3.6s ease-in-out infinite}
.d1119-roll{transform-origin:center;animation:d1119-roll 3.6s ease-in-out infinite}
@keyframes d1119-up{0%,20%{opacity:0;transform:translateY(-14px)}45%,100%{opacity:1;transform:translateY(0)}}
@keyframes d1119-nudge{0%,100%{transform:translateX(0)}50%{transform:translateX(10px)}}
@keyframes d1119-roll{0%{transform:translateX(0) rotate(0)}70%,100%{transform:translateX(90px) rotate(360deg)}}
@media (prefers-reduced-motion:reduce){.d1119-new,.d1119-new2{opacity:1}}
